def solve_tree(node, expected_output):
    op = node.operation
    if op == 0:
        return leaf_value
    children = node.children
    if op == 1:  # NOT
        child_val = 0 if expected_output == 1 else 1
        return [child_val]  # assuming one child
    elif op == 2:  # AND
        return [1 if expected_output == 1 else 0] * len(children)
    elif op == 3:  # OR
        return [1 if expected_output == 1 else 0] * len(children)
    elif op == 4:  # XOR
        if expected_output == 1:
            return [1] + [0] * (len(children) - 1)
        else:
            return [0] * len(children)
    elif op == 5:  # NAND
        return [0 if expected_output == 1 else 1] * len(children)
    elif op == 6:  # NOR
        return [0 if expected_output == 1 else 1] * len(children)
    elif op == 7:  # ALTERNATE
        if expected_output == 1:
            return [1 if i % 2 == 0 else 0 for i in range(len(children))]
        else:
            return [0] * len(children)
    elif op == 8:  # FIRST_AND_LAST_0
        return [0 if expected_output == 1 else 1] * len(children)
    elif op == 9:  # FIRST_AND_LAST_1
        return [1 if expected_output == 1 else 0] * len(children)

