def modular_sqrt(a, p):
    # Check if a is quadratic residue modulo p
    if legendre_symbol(a, p) != 1:
        return 0
    if a == 0:
        return 0
    if p == 2:
        return p
    if p % 4 == 3:
        return pow(a, (p + 1) // 4, p)
    # Factor p-1 as s * 2^e with s odd
    s = p - 1
    e = 0
    while s % 2 == 0:
        s //= 2
        e += 1
    # Find a quadratic non-residue n
    n = 2
    while legendre_symbol(n, p) != -1:
        n += 1
    x = pow(a, (s + 1) // 2, p)
    b = pow(a, s, p)
    g = pow(n, s, p)
    r = e
    while True:
        t = b
        m = 0
        for m in range(r):
            if t == 1:
                break
            t = pow(t, 2, p)
        if m == 0:
            return x
        gs = pow(g, 2 ** (r - m - 1), p)
