def rotl(value, amount, width):
    amount %= width
    return ((value << amount) | (value >> (width - amount))) & ((1 << width) - 1)

def rotr(value, amount, width):
    amount %= width
    return ((value >> amount) | (value << (width - amount))) & ((1 << width) - 1)

def invert_chunk(target, index, constants, width, chunk_size):
    # constants: dict with 'rot_a', 'rot_b', 'xor_a', 'xor_b', 'add', 'mul'
    value = rotr(target, constants['rot_b'][index], width) ^ constants['xor_d'][index]
    value = (value * pow(constants['mul'][index], -1, 1 << width)) & ((1 << width) - 1)
    value = (value - constants['add'][index]) & ((1 << width) - 1)
    value = rotr(value, constants['rot_a'][index], width) ^ constants['xor_a'][index]
    return value.to_bytes(chunk_size, 'little')

def recover_input(targets, constants, width, chunk_size):
    return b''.join(invert_chunk(t, i, constants, width, chunk_size) for i, t in enumerate(targets))

